<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;ALERT: AOF rewrite failed! Status: </span><span style="color:#E06C75;">$AOF_STATUS</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">mail</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> &quot;Redis AOF Alert&quot;</span><span style="color:#E06C75;"> $ALERT_EMAIL</span></span>
